/*
 * E-LEARNING 09 / CLOUD LEARNING LIBRARY
 * Pure Canvas 2D. Time is in seconds. One scene, seamless 25-second loop.
 * Export target: 3840 x 2160, 60 fps, 100,000,000 bits/second.
 * Canvas draws frames; the host renderer must configure the video encoder.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!ctx || !Number.isFinite(t) || minSide <= 0) return;

  const TAU = Math.PI * 2;
  const phase = (currentScene + sceneProgress) / sceneCount;
  const scale = Math.min(width / 1600, height / 900, minSide / 900);
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const ease = v => {
    v = clamp(v);
    return v < 0.5 ? 8 * v * v * v * v : 1 - Math.pow(-2 * v + 2, 4) / 2;
  };
  const smooth = (a, b, v) => {
    const p = clamp((v - a) / (b - a));
    return p * p * (3 - 2 * p);
  };
  const lerp = (a, b, p) => a + (b - a) * p;
  const C = { ink: '#2B4F61', muted: '#7A95A1', teal: '#4C9B9C', lilac: '#8592BB' };

  function rectPath(x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath(); ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function box(x, y, w, h, r, fill, stroke, lw = 1) {
    rectPath(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function circle(x, y, r, fill, stroke, lw = 1) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color, lw = 1) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function text(value, x, y, size, color, weight = 500, maxWidth = 260, align = 'left') {
    ctx.save(); ctx.font = weight + ' ' + size + 'px Arial, "DejaVu Sans", Helvetica, sans-serif';
    const measured = ctx.measureText(value).width;
    if (measured > maxWidth) {
      size *= maxWidth / measured;
      ctx.font = weight + ' ' + size + 'px Arial, "DejaVu Sans", Helvetica, sans-serif';
    }
    ctx.textAlign = align; ctx.textBaseline = 'middle'; ctx.fillStyle = color;
    ctx.fillText(value, x, y); ctx.restore();
  }
  function check(x, y, amount, color, size = 9) {
    amount = clamp(amount); if (amount <= 0) return;
    const u = Math.min(1, amount / 0.38);
    ctx.beginPath(); ctx.moveTo(x - size * 0.6, y);
    ctx.lineTo(lerp(x - size * 0.6, x - size * 0.1, u), lerp(y, y + size * 0.44, u));
    if (amount > 0.38) {
      const v = (amount - 0.38) / 0.62;
      ctx.lineTo(lerp(x - size * 0.1, x + size * 0.7, v), lerp(y + size * 0.44, y - size * 0.52, v));
    }
    ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.stroke();
  }
  function cubic(p, u) {
    const v = 1 - u;
    return [
      v * v * v * p[0] + 3 * v * v * u * p[2] + 3 * v * u * u * p[4] + u * u * u * p[6],
      v * v * v * p[1] + 3 * v * v * u * p[3] + 3 * v * u * u * p[5] + u * u * u * p[7]
    ];
  }
  function bookPage(side) {
    ctx.beginPath(); ctx.moveTo(side * 121, -108);
    ctx.lineTo(side * 28, -108); ctx.quadraticCurveTo(side * 12, -108, side * 7, -97);
    ctx.lineTo(side * 7, 31); ctx.quadraticCurveTo(side * 18, 22, side * 33, 22);
    ctx.lineTo(side * 121, 22); ctx.closePath();
  }

  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowColor = 'rgba(0,0,0,0)'; ctx.filter = 'none';
  ctx.setLineDash([]); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  const bg = ctx.createLinearGradient(0, height, width, 0);
  bg.addColorStop(0, '#0B1322'); bg.addColorStop(0.42, '#192C40');
  bg.addColorStop(0.78, '#22354B'); bg.addColorStop(1, '#142A3C');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2 + 6 * scale); ctx.scale(scale, scale);

  const cycle = phase * 3 + 0.16;
  const index = Math.floor(cycle) % 3;
  const p = cycle - Math.floor(cycle);
  const handoff = ease((p - 0.8) / 0.2);
  const weights = [0, 0, 0];
  weights[index] = 1 - handoff; weights[(index + 1) % 3] = handoff;

  const cloudFill = ctx.createLinearGradient(-300, -270, 330, 82);
  cloudFill.addColorStop(0, '#EEF4F5'); cloudFill.addColorStop(1, '#CADAE2');
  ctx.beginPath(); ctx.moveTo(-230, 82);
  ctx.bezierCurveTo(-298, 82, -340, 39, -340, -20);
  ctx.bezierCurveTo(-340, -75, -299, -120, -244, -125);
  ctx.bezierCurveTo(-234, -200, -174, -250, -102, -246);
  ctx.bezierCurveTo(-65, -291, -2, -306, 55, -283);
  ctx.bezierCurveTo(96, -266, 122, -236, 135, -201);
  ctx.bezierCurveTo(214, -225, 285, -171, 292, -102);
  ctx.bezierCurveTo(339, -91, 369, -51, 369, -5);
  ctx.bezierCurveTo(369, 46, 327, 82, 275, 82);
  ctx.closePath(); ctx.fillStyle = cloudFill; ctx.fill();
  ctx.strokeStyle = '#A4C0CF'; ctx.lineWidth = 2; ctx.stroke();
  box(-57, -232, 114, 24, 7, '#D4E4E8', '#BED2D9', 1);
  text('CLOUD SYNC', 0, -220, 9, '#678B9B', 700, 102, 'center');
  text('LEARNING LIBRARY', 0, -163, 13, C.ink, 700, 328, 'center');

  for (let i = 0; i < 3; i++) {
    const y = -65 + i * 32;
    box(-269, y, 87, 21, 5, '#D7E4E8', '#B9CED5', 1);
    circle(-256, y + 10.5, 3, '#A0BCC7');
    ctx.save(); ctx.globalAlpha = weights[i];
    circle(-256, y + 10.5, 3, i === 1 ? '#8998BC' : '#4F9B9A'); ctx.restore();
    box(-245, y + 8, 46 - i * 6, 4, 2, '#9DB9C5');
  }
  text('CONTENT', -225.5, 42, 7.5, '#8DA5AE', 700, 87, 'center');
  box(195, -57, 80, 83, 9, '#DCE8EB', '#B3CAD3', 1);
  text('INDEX', 235, -38, 8.5, '#7B99A6', 700, 64, 'center');
  for (let i = 0; i < 3; i++) {
    box(208, -20 + i * 16, 54, 4, 2, '#BDCFD7');
    box(208, -20 + i * 16, 54 * (0.26 + 0.68 * weights[i]), 4, 2, i === 1 ? '#8F9FC0' : '#65A5A3');
  }
  text('CONNECTED', 235, 44, 7.5, '#8DA5AE', 700, 91, 'center');

  ctx.beginPath(); ctx.moveTo(-132, -120); ctx.lineTo(-25, -120);
  ctx.quadraticCurveTo(-9, -120, 0, -109); ctx.quadraticCurveTo(9, -120, 25, -120);
  ctx.lineTo(132, -120); ctx.lineTo(132, 36); ctx.lineTo(28, 36);
  ctx.quadraticCurveTo(10, 36, 0, 46); ctx.quadraticCurveTo(-10, 36, -28, 36);
  ctx.lineTo(-132, 36); ctx.closePath(); ctx.fillStyle = '#47798B'; ctx.fill();
  for (const side of [-1, 1]) {
    bookPage(side);
    const page = ctx.createLinearGradient(side * 121, -108, side * 7, 29);
    page.addColorStop(0, '#F8FAF2'); page.addColorStop(1, '#E4EEE7');
    ctx.fillStyle = page; ctx.fill();
  }
  line(0, -101, 0, 34, '#2F6579', 2);
  const reading = 0.5 - 0.5 * Math.cos(TAU * phase * 3);
  box(-111, -94 + reading * 69, 88, 16, 4, '#D2E7E0');
  const widths = [70, 59, 75, 49];
  for (let i = 0; i < 4; i++) {
    box(-105, -88 + i * 23, widths[i], 4, 2, '#99B8B9');
    const w = widths[i] * ease(reading * 3 - i + 0.75);
    if (w > 0.1) box(-105, -88 + i * 23, w, 4, 2, '#5B9D98');
  }
  ctx.beginPath(); ctx.moveTo(53, -70); ctx.bezierCurveTo(53, -51, 29, -47, 29, -31);
  ctx.moveTo(63, -70); ctx.bezierCurveTo(63, -51, 91, -47, 91, -31);
  ctx.strokeStyle = '#A6C6BA'; ctx.lineWidth = 1.7; ctx.stroke();
  circle(58, -79, 12, '#7CABA6');
  circle(29, -20, 10, '#DFEEE2', '#A6C5B5', 1.1);
  circle(91, -20, 10, '#DFEEE2', '#A6C5B5', 1.1);
  check(91, -20, 1, '#528D83', 6);
  box(24, -24, 10, 8, 2, null, '#6A9F95', 1.1);
  circle(58, -79, 3.5, '#EAF3E5');
  const linkP = (phase * 6) % 1;
  ctx.save(); ctx.globalAlpha = Math.pow(Math.sin(Math.PI * linkP), 2);
  const link = cubic([53, -66, 50, -49, 29, -45, 29, -33], ease(linkP));
  circle(link[0], link[1], 2.4, '#579E94'); ctx.restore();
  ctx.beginPath(); ctx.moveTo(93, -120); ctx.lineTo(110, -120);
  ctx.lineTo(110, -75); ctx.lineTo(101.5, -81); ctx.lineTo(93, -75); ctx.closePath();
  ctx.fillStyle = '#8D9DBF'; ctx.fill();
  for (let i = 0; i < 3; i++) {
    circle(-16 + i * 16, 63, 3.1, '#AFC8CE');
    ctx.save(); ctx.globalAlpha = weights[i]; circle(-16 + i * 16, 63, 3.1, '#588E9C'); ctx.restore();
  }

  const routes = [
    [-264, 164, -264, 137, -212, 127, -212, 99],
    [0, 164, 0, 142, 0, 121, 0, 99],
    [264, 164, 264, 137, 212, 127, 212, 99]
  ];
  const labels = ['DOCUMENTS', 'VIDEO', 'EXERCISES'];
  const descriptions = ['READ & REVIEW', 'WATCH & LEARN', 'PRACTICE & APPLY'];
  for (let i = 0; i < 3; i++) {
    const cx = (i - 1) * 264;
    const portX = (i - 1) * 212;
    const r = routes[i];
    circle(portX, 92, 3.2, '#92BDCB');
    ctx.beginPath(); ctx.moveTo(r[0], r[1]); ctx.bezierCurveTo(r[2], r[3], r[4], r[5], r[6], r[7]);
    ctx.strokeStyle = '#5A8398'; ctx.lineWidth = 2.5; ctx.stroke();
    const q = (phase * 6 + i / 3) % 1;
    const packet = cubic(r, ease(q));
    ctx.save(); ctx.globalAlpha = (0.24 + 0.76 * weights[i]) * Math.pow(Math.sin(Math.PI * q), 2);
    circle(packet[0], packet[1], 4.1, i === 1 ? '#B6C3E0' : '#9BD3CB'); ctx.restore();
    box(cx - 74, 155, 66, 27, 7, '#8CAAC0', '#ACC3D0', 1);
    line(cx - 60, 164, cx - 33, 164, '#B8CFD6', 1.5);
    const folder = ctx.createLinearGradient(cx - 90, 174, cx + 90, 284);
    folder.addColorStop(0, '#E4EDF0'); folder.addColorStop(1, '#C3D7E1');
    box(cx - 90, 174, 180, 110, 14, folder, '#92B3C4', 1.3);
    ctx.save(); ctx.globalAlpha = weights[i] * 0.9;
    box(cx - 90, 174, 180, 110, 14, null, i === 1 ? '#A3B4D0' : '#8EC4BC', 2); ctx.restore();
    box(cx - 72, 188, 35, 32, 9, '#CFDFE5');
    if (i === 0) {
      box(cx - 62, 195, 15, 18, 3, null, '#5E879B', 1.5);
      line(cx - 58, 201, cx - 51, 201, '#5E879B', 1.2);
      line(cx - 58, 207, cx - 53, 207, '#5E879B', 1.2);
    } else if (i === 1) {
      ctx.beginPath(); ctx.moveTo(cx - 60, 195); ctx.lineTo(cx - 60, 213); ctx.lineTo(cx - 46, 204);
      ctx.closePath(); ctx.fillStyle = '#7B8FB1'; ctx.fill();
    } else check(cx - 54, 204, 1, '#568E89', 10);
    text(labels[i], cx - 23, 204, 10, '#4C7487', 700, 98);
    text(descriptions[i], cx - 68, 234, 8, '#7F9BA8', 600, 136);
    box(cx - 68, 254, 136, 4.5, 2.25, '#ACC5CE');
    box(cx - 68, 254, 136 * (0.24 + 0.71 * weights[i]), 4.5, 2.25, i === 1 ? '#879ABC' : '#609F9C');
    text('LEARNING MATERIAL', cx, 274, 7, '#8AA2AE', 600, 146, 'center');
  }
  ctx.restore();
}

// Export metadata only; the host must honor these encoder settings.
draw.duration = 25;
draw.fps = 60;
draw.exportSettings = Object.freeze({
  width: 3840, height: 2160, frameRate: 60, duration: 25,
  bitrate: 100000000, minBitrate: 100000000, maxBitrate: 100000000
});

/*
 * E-LEARNING 10 / ADAPTIVE LEARNING ENGINE
 * Pure Canvas 2D. Time is in seconds. One scene, seamless 25-second loop.
 * Export target: 3840 x 2160, 60 fps, 100,000,000 bits/second.
 * Canvas draws frames; the host renderer must configure the video encoder.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!ctx || !Number.isFinite(t) || minSide <= 0) return;

  const TAU = Math.PI * 2;
  const phase = (currentScene + sceneProgress) / sceneCount;
  const scale = Math.min(width / 1600, height / 900, minSide / 900);
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const ease = v => {
    v = clamp(v);
    return v < 0.5 ? 8 * v * v * v * v : 1 - Math.pow(-2 * v + 2, 4) / 2;
  };
  const smooth = (a, b, v) => {
    const p = clamp((v - a) / (b - a));
    return p * p * (3 - 2 * p);
  };
  const lerp = (a, b, p) => a + (b - a) * p;

  function rectPath(x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath(); ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function box(x, y, w, h, r, fill, stroke, lw = 1) {
    rectPath(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function circle(x, y, r, fill, stroke, lw = 1) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color, lw = 1) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function text(value, x, y, size, color, weight = 500, maxWidth = 350, align = 'left') {
    ctx.save(); ctx.font = weight + ' ' + size + 'px Arial, "DejaVu Sans", Helvetica, sans-serif';
    const measured = ctx.measureText(value).width;
    if (measured > maxWidth) {
      size *= maxWidth / measured;
      ctx.font = weight + ' ' + size + 'px Arial, "DejaVu Sans", Helvetica, sans-serif';
    }
    ctx.textAlign = align; ctx.textBaseline = 'middle'; ctx.fillStyle = color;
    ctx.fillText(value, x, y); ctx.restore();
  }
  function check(x, y, color, size = 11) {
    ctx.beginPath(); ctx.moveTo(x - size * 0.6, y);
    ctx.lineTo(x - size * 0.1, y + size * 0.44); ctx.lineTo(x + size * 0.7, y - size * 0.52);
    ctx.strokeStyle = color; ctx.lineWidth = 2.1; ctx.stroke();
  }
  function pagePath(side) {
    ctx.beginPath(); ctx.moveTo(side * 112, -94); ctx.lineTo(side * 27, -94);
    ctx.quadraticCurveTo(side * 13, -94, side * 7, -84);
    ctx.lineTo(side * 7, 40); ctx.quadraticCurveTo(side * 18, 31, side * 33, 31);
    ctx.lineTo(side * 112, 31); ctx.closePath();
  }

  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowColor = 'rgba(0,0,0,0)'; ctx.filter = 'none';
  ctx.setLineDash([]); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  const bg = ctx.createLinearGradient(0, 0, width, height);
  bg.addColorStop(0, '#0E1521'); bg.addColorStop(0.43, '#1C293D');
  bg.addColorStop(0.78, '#243448'); bg.addColorStop(1, '#142A38');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2); ctx.scale(scale, scale);

  const cycle = phase * 4 + 0.15;
  const index = Math.floor(cycle) % 4;
  const p = cycle - Math.floor(cycle);
  const previous = (index + 3) % 4;
  const focusIn = ease(p / 0.12);
  const weights = [0, 0, 0, 0];
  weights[previous] = 1 - focusIn; weights[index] = focusIn;
  const openness = smooth(0.1, 0.24, p) * (1 - smooth(0.77, 0.93, p));
  const delivery = ease((p - 0.24) / 0.43);
  const deliveryAlpha = smooth(0.24, 0.3, p) * (1 - smooth(0.61, 0.67, p));
  const levels = [0, 1, 2, 1];
  const level = lerp(levels[previous], levels[index], ease((p - 0.66) / 0.21));
  const sources = [
    { x: 0, y: -326, label: 'CONTENT', color: '#79B9BE', sx: 0, sy: -286, ex: 0, ey: -242, gx: 0, gy: -264, vertical: true },
    { x: -408, y: 0, label: 'PRACTICE', color: '#9C9BCB', sx: -369, sy: 0, ex: -257, ey: 0, gx: -310, gy: 0, vertical: false },
    { x: 408, y: 0, label: 'FEEDBACK', color: '#83BEAD', sx: 369, sy: 0, ex: 257, ey: 0, gx: 310, gy: 0, vertical: false },
    { x: 0, y: 326, label: 'PROGRESS', color: '#A0B1D0', sx: 0, sy: 286, ex: 0, ey: 242, gx: 0, gy: 264, vertical: true }
  ];

  // Each source has an isolated lane. Packets only cross gates while open.
  for (let i = 0; i < 4; i++) {
    const s = sources[i];
    line(s.sx, s.sy, s.ex, s.ey, '#4A6B81', 2.5);
    const gateOpen = i === index ? openness : 0;
    const gap = 2 + 9 * gateOpen;
    ctx.save(); ctx.translate(s.gx, s.gy);
    if (s.vertical) ctx.rotate(Math.PI / 2);
    box(-6, -gap - 9, 12, 9, 3, '#7793A7', '#A1B4C2', 0.8);
    box(-6, gap, 12, 9, 3, '#7793A7', '#A1B4C2', 0.8);
    ctx.save(); ctx.globalAlpha = gateOpen;
    box(-6, -gap - 9, 12, 9, 3, s.color);
    box(-6, gap, 12, 9, 3, s.color); ctx.restore(); ctx.restore();
    if (i === index) {
      ctx.save(); ctx.globalAlpha = deliveryAlpha;
      circle(lerp(s.sx, s.ex, delivery), lerp(s.sy, s.ey, delivery), 3.5, '#C1E5DC', s.color, 1);
      ctx.restore();
    }
    box(s.x - 32, s.y - 32, 64, 64, 17, '#2C455B', '#668397', 1.3);
    ctx.save(); ctx.globalAlpha = weights[i];
    box(s.x - 32, s.y - 32, 64, 64, 17, '#365F6A', s.color, 1.7); ctx.restore();
    if (i === 0) {
      box(s.x - 11, s.y - 13, 22, 27, 4, null, '#B6D5D6', 1.8);
      line(s.x - 6, s.y - 5, s.x + 6, s.y - 5, '#B6D5D6', 1.5);
      line(s.x - 6, s.y + 2, s.x + 6, s.y + 2, '#B6D5D6', 1.5);
      line(s.x - 6, s.y + 9, s.x + 2, s.y + 9, '#B6D5D6', 1.5);
    } else if (i === 1) {
      for (let j = 0; j < 3; j++) {
        const yy = s.y - 10 + j * 10;
        line(s.x - 13, yy, s.x + 13, yy, '#B3B7DB', 1.7);
        circle(s.x - 6 + j * 5, yy, 3, '#CFD0E4');
      }
    } else if (i === 2) {
      circle(s.x, s.y, 15, null, '#B7D9CA', 1.7);
      check(s.x, s.y, '#B7D9CA', 12);
    } else {
      for (let j = 0; j < 3; j++) box(s.x - 13 + j * 10, s.y + 12 - (j + 1) * 7, 6, (j + 1) * 7, 2, '#B0C5DD');
    }
    if (s.vertical) text(s.label, s.x + 49, s.y, 10, '#A2BBCB', 700, 146);
    else text(s.label, s.x, s.y + 55, 10, '#A2BBCB', 700, 153, 'center');
  }

  // Contact pins remain rigid and evenly spaced on all four sides of the chip.
  for (let j = 0; j < 5; j++) {
    const v = -136 + j * 68;
    box(v - 7, -234, 14, 29, 4, '#778E9D', '#A5B4BB', 0.8);
    box(v - 7, 205, 14, 29, 4, '#778E9D', '#A5B4BB', 0.8);
    box(-249, v - 7, 29, 14, 4, '#778E9D', '#A5B4BB', 0.8);
